import React from "react";

export const Newsletter = () => {
  return (
    <>
      <section className="cta-full">
        <div className="cta-inner">

          <div className="cta-left">
            <h2>Let’s Turn Ideas Into Reality ✨</h2>
            <p>
              Passionate about building modern and responsive web experiences.
              Open to internships, freelance collaborations, and full-time opportunities.
              Let’s connect and create something impactful together.
            </p>
          </div>

          <div className="cta-right">
            <a href="#connect" className="cta-btn">
              Let’s Connect
            </a>
          </div>

        </div>
      </section>

      <style>{`

        /* FULL WIDTH SECTION */
        .cta-full {
          width: 100%;
          padding: 120px 0;
          background: linear-gradient(135deg, #6a11cb 0%, #2575fc 0%, #b91372 100%);
        }

        /* CENTER CONTENT */
        .cta-inner {
          max-width: 1200px;
          margin: auto;
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 0 60px;
          gap: 40px;
        }

        .cta-left h2 {
          font-size: 42px;
          font-weight: 800;
          color: #ffffff;
          margin-bottom: 20px;
        }

        .cta-left p {
          color: #f3f3f3;
          font-size: 17px;
          line-height: 1.8;
          max-width: 650px;
        }

        /* BUTTON */
        .cta-btn {
          display: inline-block;
          background: #ffffff;
          color: #6a11cb;
          padding: 18px 55px;
          border-radius: 50px;
          font-size: 17px;
          font-weight: 600;
          text-decoration: none;
          transition: all 0.4s ease;
          box-shadow: 0 12px 30px rgba(0,0,0,0.3);
        }

        .cta-btn:hover {
          background: #000000;
          color: #ffffff;
          transform: scale(1.1);
          box-shadow: 0 20px 40px rgba(0,0,0,0.5);
        }

        /* RESPONSIVE */
        @media (max-width: 992px) {
          .cta-inner {
            flex-direction: column;
            text-align: center;
            padding: 0 30px;
          }

          .cta-left h2 {
            font-size: 30px;
          }
        }

      `}</style>
    </>
  );
};
